async function workProgress(conn: PoolConnection, workOrderId: number) { const [counts] = await conn.query<RowDataPacket[]>(`SELECT COUNT(*) total,SUM(status='completed') completed FROM work_order_complaints WHERE work_order_id=?`, [workOrderId]); const total = Number(counts[0].total), completed = Number(counts[0].completed); return completed === total ? 'completed' : completed === 0 ? 'pending' : 'partially_completed'; }
