router.get('/billing/:jobCardId',requirePermission('BILLING_VIEW'),asyncRoute(async(req,res)=>{const companyId=Number(req.user!.company_id),scope=branchScope(req,'j');const rows=await query<RowDataPacket&Record<string,unknown>>(`${jobSelect} WHERE j.id=? AND j.company_id=?${scope.sql} AND j.deleted_at IS NULL AND j.status<>'draft'`,[req.params.jobCardId,companyId,...scope.params]);if(!rows[0]){res.status(404).json({message:'Approved Job Card not found for billing'});return}const workOrders=await query<RowDataPacket&Record<string,unknown>>(`${workSelect} WHERE w.job_card_id=? AND w.company_id=? AND w.deleted_at IS NULL LIMIT 1`,[req.params.jobCardId,companyId]);const workOrder=workOrders[0]??null;const complaints=await query<RowDataPacket&Record<string,unknown>>('SELECT * FROM job_card_complaints WHERE job_card_id=? AND company_id=? AND is_deleted=0 ORDER BY sort_order,id',[req.params.jobCardId,companyId]);const spares=workOrder?await query<RowDataPacket&Record<string,unknown>>('SELECT * FROM work_order_spares WHERE work_order_id=? AND company_id=? AND is_deleted=0 ORDER BY sort_order,id',[workOrder.id,companyId]):[];const receipts=await query<RowDataPacket&Record<string,unknown>>('SELECT * FROM payment_receipts WHERE job_card_id=? AND company_id=? AND is_deleted=0 ORDER BY receipt_date,id',[req.params.jobCardId,companyId]);const additionalPaid=receipts.reduce((sum,row)=>sum+Number(row.amount??0),0);const totalPaid=Number(rows[0].advance_paid??0)+additionalPaid,finalBill=complaints.reduce((sum,row)=>sum+Number(row.cost??0),0)+Number(workOrder?.service_cost??0)+Number(workOrder?.labour_cost??0)+spares.reduce((sum,row)=>sum+Number(row.total??Number(row.quantity||0)*Number(row.rate||0)),0);res.json({data:{...rows[0],customer_contact:rows[0].customer_mobile||rows[0].customer_contact,work_order:workOrder,complaints,spares,receipts,additional_paid:additionalPaid,total_paid:totalPaid,bill_balance:Math.max(0,finalBill-totalPaid)}})}));
const receiptSchema = z.object({ receipt_date: z.string().date(), amount: z.coerce.number().positive(), payment_mode: z.enum(['CASH', 'UPI', 'CARD', 'BANK_TRANSFER', 'OTHER']), reference_number: z.string().trim().max(100).optional().nullable(), remarks: z.string().trim().max(255).optional().nullable() });
router.post('/accounts/:jobCardId/receipts', requirePermission('PAYMENT_RECEIVE'), asyncRoute(async (req, res) => { const parsed = receiptSchema.safeParse(req.body); if (!parsed.success) {
    res.status(422).json({ message: parsed.error.issues[0].message });
    return;
} const data = parsed.data; const result = await withTransaction(async (conn) => { const companyId=Number(req.user!.company_id);const [jobs] = await conn.query<RowDataPacket[]>(`SELECT j.*,COALESCE(cw.work_total,0) work_total,COALESCE(pay.receipts,0) receipts,COALESCE(w.service_cost,0) service_cost,COALESCE(w.labour_cost,0) labour_cost,COALESCE(sp.spare_total,0) spare_total FROM job_cards j LEFT JOIN work_orders w ON w.job_card_id=j.id AND w.company_id=j.company_id AND w.deleted_at IS NULL LEFT JOIN (SELECT job_card_id,COALESCE(SUM(cost),0) work_total FROM job_card_complaints WHERE company_id=? AND is_deleted=0 GROUP BY job_card_id) cw ON cw.job_card_id=j.id LEFT JOIN (SELECT job_card_id,COALESCE(SUM(amount),0) receipts FROM payment_receipts WHERE company_id=? AND is_deleted=0 GROUP BY job_card_id) pay ON pay.job_card_id=j.id LEFT JOIN (SELECT work_order_id,COALESCE(SUM(total),0) spare_total FROM work_order_spares WHERE company_id=? AND is_deleted=0 GROUP BY work_order_id) sp ON sp.work_order_id=w.id WHERE j.id=? AND j.company_id=? AND j.deleted_at IS NULL GROUP BY j.id,w.id FOR UPDATE`, [companyId,companyId,companyId,req.params.jobCardId,companyId]); const job = jobs[0]; if (!job)
    throw new Error('Job Card not found'); const billTotal = Number(job.work_total) + Number(job.service_cost) + Number(job.labour_cost) + Number(job.spare_total), balance = billTotal - Number(job.advance_paid) - Number(job.receipts); if (data.amount > balance)
    throw new Error('Payment cannot exceed current balance'); const no = await nextNumber(conn, 'PAYMENT_RECEIPT', Number(job.financial_year_id), 'RCPT',companyId); const [wo] = await conn.query<RowDataPacket[]>('SELECT id FROM work_orders WHERE job_card_id=? AND company_id=? AND deleted_at IS NULL', [job.id,companyId]); await conn.execute('INSERT INTO payment_receipts(company_id,financial_year_id,job_card_id,work_order_id,receipt_no,receipt_date,amount,payment_mode,reference_number,remarks,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)', [companyId,job.financial_year_id, job.id, wo[0]?.id ?? null, no, data.receipt_date, data.amount, data.payment_mode, data.reference_number || null, data.remarks || null, req.user!.id]); return no; }); res.status(201).json({ message: `Payment ${result} received` }); }));
router.delete('/accounts/receipts/:id', requirePermission('PAYMENT_DELETE'), asyncRoute(async (req, res) => { await execute('UPDATE payment_receipts SET is_deleted=1,deleted_at=NOW(),deleted_by=? WHERE id=? AND company_id=? AND is_deleted=0', [req.user!.id, req.params.id,req.user!.company_id]); res.json({ message: 'Payment receipt deleted' }); }));
export default router;

